const express = require('express');
const { Client } = require('@elastic/elasticsearch');
const db = require('../db');

const es = new Client({ node: process.env.ELASTICSEARCH_URL || 'http://localhost:9200' });
const app = express();

app.get('/api/apm/spans/by-session/:sessionId', async (req, res) => {
  const { sessionId } = req.params;

  // Validate that the targeted session belongs to the requesting user
  const session = await db('user_sessions')
    .where({ id: sessionId, user_id: req.user.id })
    .first();

  if (!session) {
    return res.status(403).json({ error: 'Access denied to target session telemetry' });
  }

  const result = await es.search({
    index: 'otel-spans-*',
    body: {
      query: {
        bool: {
          must: [
            { term: { 'attributes.session_id.keyword': sessionId } },
            { term: { 'attributes.user_id.keyword': req.user.id } }
          ]
        }
      },
      size: 50
    }
  });

  const hits = result.hits.hits.map(h => ({
    spanId: h._source.span_id,
    name: h._source.name,
    attributes: h._source.attributes,
    durationMs: h._source.duration_ms
  }));

  return res.json({ sessionId, spans: hits });
});

module.exports = app;
